package io.knowledgebrain.content;
import java.util.*;import java.time.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;
import org.springframework.web.server.ResponseStatusException;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_CONTENT_DATABASE_URL",matches=".+")
class QuestionStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;QuestionStore store;String schema;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;String trace="e".repeat(32);
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_CONTENT_DATABASE_URL"));ds.setUser("brain_content");ds.setPassword(System.getenv("BRAIN_TEST_CONTENT_DATABASE_PASSWORD"));schema="question_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new QuestionStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 @AfterEach void clean(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 QuestionStore.Input input(String title){return new QuestionStore.Input(title," \n\tprivate context\r\n ","Draft answer","OPEN");}
 QuestionStore.Question create(){return store.create(space,actor,key(),input("Saved title"),trace).question();}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
 void status(int code,Runnable fn){assertEquals(code,assertThrows(ResponseStatusException.class,fn::run).getStatusCode().value());}
 @Test void createRetriesReplayOriginalSnapshotAfterEditingArchivalAndPrincipalChange(){var key=key();var first=store.create(space,actor,key,input("First"),trace);assertFalse(first.replay());var v=first.question();store.change(space,v.questionId(),actor,1,input("Later"),false,trace);store.change(space,v.questionId(),actor,2,null,true,trace);var replay=store.create(space,ids.next(),key,input("First"),trace);assertTrue(replay.replay());assertEquals(v,replay.question());status(409,()->store.create(space,actor,key,input("Different"),trace));assertEquals(1,count("question"));assertEquals(3,count("question_revision"));assertEquals(3,count("outbox_event"));assertEquals(actor,store.history(space,v.questionId(),Long.MAX_VALUE,10).getLast().actorId());}
 @Test void independentStrongVersionsNoopAndRetiredHistorySurviveNewStore(){var v=create();for(int n=1;n<=6;n++)v=store.change(space,v.questionId(),actor,n,input("Update "+n),false,trace);var id=v.questionId();assertEquals(v,store.change(space,id,actor,7,input("Update 6"),false,trace));status(412,()->store.change(space,id,actor,1,input("Update 6"),false,trace));assertEquals(List.of(7L,6L,5L,4L,3L),store.history(space,id,Long.MAX_VALUE,5).stream().map(QuestionStore.Revision::version).toList());assertEquals(List.of(2L,1L),store.history(space,id,3,5).stream().map(QuestionStore.Revision::version).toList());var retired=store.change(space,id,actor,7,null,true,trace);assertEquals(retired,new QuestionStore(ds,Clock.systemUTC()).get(space,id));assertEquals(retired,store.change(space,id,actor,8,null,true,trace));status(404,()->store.change(space,id,actor,8,input("Blocked"),false,trace));assertEquals(8,count("question_revision"));}
 @Test void controlledOutboxFailureRollsBackCreationAndMutationIncludingKeys(){sql.execute("CREATE FUNCTION fail_question() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'controlled question failure'; END $$");sql.execute("CREATE TRIGGER fail_question BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_question()");var key=key();assertThrows(RuntimeException.class,()->store.create(space,actor,key,input("Rollback"),trace));assertEquals(0,count("question"));assertEquals(0,count("question_revision"));sql.execute("ALTER TABLE outbox_event DISABLE TRIGGER fail_question");var v=store.create(space,actor,key,input("Rollback"),trace).question();sql.execute("ALTER TABLE outbox_event ENABLE TRIGGER fail_question");assertThrows(RuntimeException.class,()->store.change(space,v.questionId(),actor,1,input("Lost"),false,trace));assertEquals(v,store.get(space,v.questionId()));assertEquals(1,count("question_revision"));}
 @Test void concurrentCreateAndEditsHaveOneCanonicalOutcome()throws Exception{var key=key();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);Callable<QuestionStore.Created> task=()->{gate.await();return store.create(space,actor,key,input("Concurrent"),trace);};var a=pool.submit(task);var b=pool.submit(task);var x=a.get();var y=b.get();assertEquals(x.question(),y.question());assertNotEquals(x.replay(),y.replay());var id=x.question().questionId();var gate2=new CyclicBarrier(2);Callable<Integer> write=()->{gate2.await();try{store.change(space,id,actor,1,input("Winner"),false,trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}};var c=pool.submit(write);var e=pool.submit(write);assertEquals(Set.of(200,412),Set.of(c.get(),e.get()));}assertEquals(1,count("question"));assertEquals(2,count("outbox_event"));}
 @Test void duplicateQuestionsKeepDistinctIdsAndCursorPagesCannotCrossSpaceOrLifecycle(){for(int n=0;n<23;n++)create();var a=store.list(space,"ACTIVE","ALL",null,20);var b=store.list(space,"ACTIVE","ALL",a.nextAfter(),20);assertEquals(20,a.items().size());assertEquals(3,b.items().size());assertNull(b.nextAfter());assertEquals(23,a.items().stream().map(QuestionStore.Summary::questionId).distinct().count()+b.items().stream().map(QuestionStore.Summary::questionId).distinct().count());status(400,()->store.list(actor,"ACTIVE","ALL",a.nextAfter(),20));status(400,()->store.list(space,"RETIRED","ALL",a.nextAfter(),20));status(404,()->store.get(actor,a.items().getFirst().questionId()));assertTrue(store.list(actor,"ACTIVE","ALL",null,20).items().isEmpty());}
 @Test void questionWritesKeepExistingNoteContentAndEventsIndependent(){var notes=new NoteStore(ds,Clock.systemUTC());var note=notes.create(space,actor,"Own note","Unchanged markdown",trace);var v=create();store.change(space,v.questionId(),actor,1,input("Edit only question"),false,trace);assertEquals(note,notes.get(space,note.noteId()));assertEquals(1,notes.history(space,note.noteId(),Long.MAX_VALUE,10).size());assertEquals(2,sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype='question'",Integer.class));}
 @Test void answerRequiredForResolutionReopeningRetainsAnswerAndFilteredCursorsAreBound(){
  var v=create();var invalid=new QuestionStore.Input(v.title(),v.context()," \n\t","ANSWERED");status(400,()->store.change(space,v.questionId(),actor,1,invalid,false,trace));assertEquals(1,count("question_revision"));
  var answered=store.change(space,v.questionId(),actor,1,new QuestionStore.Input(v.title(),v.context(),"My explicit answer","ANSWERED"),false,trace);assertEquals("ANSWERED",answered.status());assertEquals(1,store.list(space,"ACTIVE","ANSWERED",null,20).items().size());assertTrue(store.list(space,"ACTIVE","OPEN",null,20).items().isEmpty());
  var reopened=store.change(space,v.questionId(),actor,2,new QuestionStore.Input(v.title(),v.context(),answered.answer(),"OPEN"),false,trace);assertEquals(answered.answer(),reopened.answer());assertEquals("ANSWERED",store.history(space,v.questionId(),3,5).getFirst().snapshot().status());
  create();var page=store.list(space,"ACTIVE","OPEN",null,1);assertNotNull(page.nextAfter());status(400,()->store.list(space,"ACTIVE","ANSWERED",page.nextAfter(),1));status(400,()->store.list(space,"ACTIVE","ALL",page.nextAfter(),1));
 }
}
